LOGIN_HTML = r'''<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Araştırma İzinleri Ön İnceleme</title><style>*{box-sizing:border-box}body{margin:0;font-family:Arial,Helvetica,sans-serif;background:linear-gradient(135deg,#082f58,#0d5a94);min-height:100vh;display:grid;place-items:center;color:#0d2b4a}.box{width:min(440px,92vw);background:#fff;border-radius:18px;padding:32px;box-shadow:0 24px 70px #001b3680}.mark{width:72px;height:72px;border-radius:50%;display:grid;place-items:center;background:#0b4c82;color:#fff;font-weight:900;font-size:24px;margin:auto}.box h1{text-align:center;font-size:22px;margin:18px 0 6px}.box p{text-align:center;color:#5c6c7c;line-height:1.5}.box label{display:block;font-weight:700;margin:22px 0 8px}.box input{width:100%;padding:14px;border:1px solid #cad7e3;border-radius:10px;font-size:17px}.box button{width:100%;margin-top:16px;padding:14px;border:0;border-radius:10px;background:#0877d8;color:#fff;font-size:17px;font-weight:800;cursor:pointer}.error{padding:11px;border-radius:8px;background:#fee7e9;color:#a31522;margin-top:14px;font-weight:700}.note{font-size:12px;color:#6e7b88;margin-top:18px;text-align:center}</style></head><body><form class="box" method="post" action="/login"><div class="mark">Aİ</div><h1>Araştırma Uygulama İzinleri</h1><p>Başvuru ve Değerlendirme Ön İnceleme Programı</p><!--ERROR--><label for="password">Program Parolası</label><input id="password" name="password" type="password" required autofocus autocomplete="current-password"><button type="submit">GİRİŞ YAP</button><div class="note">Bu araç otomatik ön inceleme yapar; resmî nihai karar sistemi değildir.</div></form></body></html>'''

APP_HTML = r'''<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Araştırma Uygulama İzinleri Ön İnceleme</title><style>
*{box-sizing:border-box}body{margin:0;font-family:Arial,Helvetica,sans-serif;background:#f1f6fa;color:#17324d;font-size:14px}.top{height:74px;background:linear-gradient(90deg,#0c3d6b,#084b80);color:#fff;display:flex;align-items:center;padding:0 24px;gap:15px;position:sticky;top:0;z-index:20;box-shadow:0 2px 10px #0002}.seal{width:54px;height:54px;border:2px solid #fff;border-radius:50%;display:grid;place-items:center;font-weight:900}.brand b{display:block;font-size:18px}.brand span{display:block;font-size:14px;margin-top:7px}.logout{margin-left:auto;color:#fff;text-decoration:none;font-weight:800}.layout{display:grid;grid-template-columns:220px minmax(620px,1fr) 350px;max-width:1600px;margin:auto}.side{background:#f8fbfd;min-height:calc(100vh - 74px);border-right:1px solid #dfe9f2;padding:14px 10px}.nav{padding:13px 14px;border-radius:8px;margin:4px 0;font-weight:700}.nav.active{background:#d9ecff;color:#0068c9}.disclaimer{font-size:11px;color:#6a7987;line-height:1.5;margin:24px 10px}.content,.right{padding:12px}.card{background:#fff;border:1px solid #dfe8ef;border-radius:10px;box-shadow:0 2px 8px #16334f0a;margin-bottom:12px;padding:14px}.card h2{font-size:17px;margin:0 0 12px;border-left:4px solid #0b78dc;padding-left:10px}.hero h1{margin:0;font-size:22px}.hero p{margin:6px 0 0;color:#677889}.steps{display:flex;align-items:center;gap:8px;margin-top:18px}.step{display:flex;flex-direction:column;align-items:center;min-width:105px;text-align:center;color:#667789}.step b{width:33px;height:33px;border-radius:50%;display:grid;place-items:center;background:#d5dde5}.step.on b{background:#0877d8;color:white}.line{height:2px;background:#cbd7e1;flex:1}.formgrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px 14px}.formgrid label{font-size:12px;font-weight:700}.formgrid input,.formgrid select{display:block;width:100%;margin-top:5px;padding:9px;border:1px solid #ccd8e3;border-radius:7px;background:#fff}.sectionhead{display:flex;justify-content:space-between;align-items:center}.primary,.analyze,.ghost,.reportbtn,.linkbtn{border:0;border-radius:7px;padding:10px 15px;font-weight:800;cursor:pointer}.primary,.analyze{background:#0877d8;color:#fff}.analyze{font-size:16px;min-width:150px}.analyze:disabled{opacity:.45;cursor:not-allowed}.ghost,.reportbtn,.linkbtn{background:#eaf4fd;color:#0b5fae}.drop{border:2px dashed #9ebbd4;border-radius:9px;padding:20px;text-align:center;color:#42617d;margin:10px 0}.drop span{display:block;font-size:12px;margin-top:6px;color:#7b8c9b}.filecards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.filecard{border:1px solid #dbe5ed;border-radius:8px;padding:9px;display:flex;align-items:center;gap:8px;background:#fbfdff}.fileicon{background:#e53935;color:#fff;font-size:10px;font-weight:900;padding:8px 5px;border-radius:4px}.filemeta{min-width:0;flex:1}.filemeta b{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.filemeta span{font-size:11px;color:#718292}.remove{border:0;background:transparent;font-size:18px;cursor:pointer}.actions{display:flex;gap:10px;align-items:center;margin-top:12px}.progress{font-size:12px;color:#4c6479}.tablewrap{overflow:auto}.tablewrap table{width:100%;border-collapse:collapse;min-width:780px}.tablewrap th{background:#eef4f8;text-align:left;padding:10px;font-size:12px}.tablewrap td{border-bottom:1px solid #e7edf2;padding:9px;vertical-align:top}.status{display:inline-block;padding:5px 8px;border-radius:14px;font-weight:800;font-size:12px}.s-Uygun{background:#dcf7e6;color:#087636}.s-EksikBelge{background:#fff1c9;color:#8b6500}.s-UygunDeğil{background:#ffe0e0;color:#b21424}.s-Uzmanİncelemesi{background:#e7e8ff;color:#4346a8}.s-Uygulanmaz{background:#edf1f4;color:#677684}.detailrow{display:none;background:#fbfdff}.detail{display:grid;grid-template-columns:1fr 1fr;gap:10px}.detail div{border:1px solid #e4ebf1;border-radius:7px;padding:9px}.detail b{display:block;color:#0a5fae;margin-bottom:4px}.right{padding-left:0}.right .card{position:relative}.overall{display:flex;align-items:center;gap:12px;border-radius:10px;padding:16px;background:#edf3f7}.overall.good{background:#dcfae9;color:#087536}.overall.bad{background:#ffe3e5;color:#b81526}.overall.warn{background:#fff0c8;color:#8a6200}.overall.expert{background:#e9eaff;color:#4346a8}.big{width:54px;height:54px;border-radius:50%;display:grid;place-items:center;background:currentColor;color:#fff;font-size:29px;font-weight:900}.overall h3{margin:0;font-size:24px}.overall p{margin:5px 0 0}.counters{display:grid;grid-template-columns:repeat(2,1fr);gap:7px;margin-top:10px}.counter{border:1px solid #e1e8ee;border-radius:8px;padding:8px;display:flex;justify-content:space-between}.sideitem{border-left:4px solid #cc2534;background:#fff1f2;border-radius:6px;padding:9px;margin:7px 0;font-size:12px}.sideitem.good{border-color:#0b8d47;background:#effbf4}.reportbtn{width:100%;margin-top:8px}.riskgrid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.risk{border:1px solid #e2e9ef;border-radius:8px;padding:10px}.risktop{display:flex;justify-content:space-between;gap:8px;font-weight:800}.level{font-size:11px;padding:3px 6px;border-radius:10px;background:#edf2f6}.l-Yüksek,.l-Kritik{background:#ffe0e3;color:#aa1624}.l-Orta{background:#fff0c8;color:#876000}.l-SinyalYok{background:#def5e7;color:#087536}.l-Değerlendirilemedi{background:#e9ecf2;color:#596779}.noteBox{line-height:1.6;background:#f8fbfd;border-radius:8px;padding:12px}.muted{color:#788997}@media(max-width:1100px){.layout{grid-template-columns:75px 1fr}.side .nav span{display:none}.right{grid-column:2;padding-left:12px}.filecards{grid-template-columns:1fr 1fr}}@media(max-width:760px){.layout{display:block}.side{display:none}.right{padding:12px}.formgrid,.riskgrid{grid-template-columns:1fr}.filecards{grid-template-columns:1fr}.steps{overflow:auto}.brand span{display:none}}
@media print{.side,.top,.actions,.drop,.filecards,.primary,.linkbtn,.right .reportbtn{display:none!important}.layout{display:block}.content,.right{padding:0}.card{box-shadow:none;break-inside:avoid}.formgrid{grid-template-columns:repeat(3,1fr)}}
</style></head><body><header class="top"><div class="seal">Aİ</div><div class="brand"><b>Araştırma Uygulama İzinleri</b><span>Başvuru ve Değerlendirme Ön İnceleme Sistemi</span></div><a class="logout" href="/logout">Çıkış</a></header><div class="layout"><aside class="side"><div class="nav">⌂ <span>Ana Sayfa</span></div><div class="nav active">▣ <span>Başvuru İnceleme</span></div><div class="nav">☷ <span>Başvurularım</span></div><div class="nav">▥ <span>Raporlar</span></div><div class="nav">✓ <span>Kriterler</span></div><div class="disclaimer">Bu araç resmî karar sistemi değildir. Yüklenen belgeler üzerinde otomatik ön inceleme yapar.</div></aside><main class="content"><section class="card hero"><h1>Başvuru İnceleme</h1><p>Başvuruyu 30 resmî kriter ve 20 ayrı çocuk/kişisel veri ön kontrolü üzerinden inceleyin.</p><div class="steps"><div class="step on"><b>1</b><span>Belgeleri Yükle</span></div><div class="line"></div><div class="step"><b>2</b><span>Otomatik İnceleme</span></div><div class="line"></div><div class="step"><b>3</b><span>Sonucu Görüntüle</span></div><div class="line"></div><div class="step"><b>4</b><span>Rapor Oluştur</span></div></div></section><section class="card"><h2>Başvuru Bilgileri</h2><div class="formgrid">
<label>Araştırma Başlığı<input id="research_title"></label><label>Başvuru Türü<select id="application_type"><option>Akademisyen / Öğrenci</option><option>Bağımsız Araştırmacı</option><option>Kamu Kurumu Temsilcisi</option><option>STK Temsilcisi</option><option>Millî Eğitim Birim Temsilcisi</option><option>Zorunlu Eğitime Devam Eden Öğrenci</option></select></label><label>Araştırmacı Öğrenci mi?<select id="is_student"><option value="yes">Evet</option><option value="no">Hayır</option></select></label><label>Araştırma Niteliği<input id="research_nature" placeholder="Yüksek lisans tezi, proje, 2204-A..."></label><label>Başvurunun Yapıldığı Ülke<input id="country" value="Türkiye"></label><label>Unvan<input id="title"></label><label>Meslek<input id="profession"></label><label>Çalıştığı Kurum<input id="institution"></label><label>Bağlı Olduğu Kurum<input id="parent_institution"></label><label>Adres<input id="address"></label><label>Telefon<input id="phone"></label><label>E-posta<input id="email" type="email"></label><label>Katılımcı Grubu<input id="participant_group" placeholder="Öğrenci, öğretmen, veli..."></label><label>Uygulama İlleri<input id="cities" placeholder="Ankara, Konya"></label><label>Uygulama Birimi<input id="unit" placeholder="Ortaokul, il MEM..."></label><label>Sistemde Beyan Edilen Araçlar<input id="declared_tools" placeholder="Ölçek A; Görüşme Formu B"></label><label>Yabancı Dilde Belge<select id="foreign_docs"><option value="no">Hayır</option><option value="yes">Evet</option></select></label><label>Ses/Görüntü Kaydı<select id="av_record"><option value="no">Hayır</option><option value="yes">Evet</option></select></label><label>Reşit Olmayan Katılımcı<select id="minors"><option value="yes">Evet</option><option value="no">Hayır</option></select></label><label>Veri Toplama Aracı Kaynağı<select id="tool_origin"><option value="unknown">Bilinmiyor</option><option value="self">Araştırmacı geliştirdi</option><option value="previous">Daha önce kullanılmış araç</option></select></label><label>Mükerrer Başvuru<select id="duplicate"><option value="unknown">Bilinmiyor / Sistem kontrolü gerekli</option><option value="no">Mükerrer başvuru yok</option><option value="yes">Mükerrer başvuru var</option></select></label>
</div></section><section class="card"><div class="sectionhead"><h2>Belgeler</h2><button class="primary" id="pickBtn">＋ Dosya Yükle</button><input type="file" id="fileInput" multiple accept=".pdf,.docx,.txt,.md,.csv" hidden></div><div id="drop" class="drop"><b>Belgeleri buraya sürükleyin</b><span>PDF, DOCX, TXT, MD ve CSV • Birden fazla belge birlikte incelenebilir</span></div><div id="fileCards" class="filecards"></div><div class="actions"><button id="analyzeBtn" class="analyze" disabled>İNCELE</button><button id="clearBtn" class="ghost">Temizle</button><span id="progress" class="progress"></span></div></section><section class="card"><div class="sectionhead"><h2>Kriter Değerlendirme Sonuçları (30 Kriter)</h2><button id="expandAll" class="linkbtn">Tümünü Genişlet</button></div><div class="tablewrap"><table><thead><tr><th>No</th><th>Kriter</th><th>Durum</th><th>Açıklama</th></tr></thead><tbody id="criteriaBody"></tbody></table></div></section><section class="card"><h2>Çocuk Koruma ve Kişisel Veri Risk Analizi</h2><p class="muted">Bu 20 kontrol, 30 resmî kriteri değiştirmez; ayrı operasyonel ön kontroldür.</p><div id="riskGrid" class="riskgrid"></div></section><section class="card"><h2>İnceleme Notu</h2><div id="note" class="noteBox">Belgeler incelendikten sonra otomatik ön inceleme notu burada oluşacaktır.</div></section></main><aside class="right"><section class="card"><h2>Genel Sonuç</h2><div id="overall" class="overall"><div class="big">…</div><div><h3>İNCELEME BEKLİYOR</h3><p>Belgeleri yükleyip İNCELE düğmesine basın.</p></div></div><div id="counters" class="counters"></div></section><section class="card"><h2>Uygun Olmayan / İncelenecek Kriterler</h2><div id="issues" class="muted">Henüz sonuç yok.</div></section><section class="card"><h2>Öne Çıkan Uygunluklar</h2><div id="strengths" class="muted">Henüz sonuç yok.</div></section><section class="card"><h2>Rapor</h2><button id="printBtn" class="reportbtn">Detaylı Raporu Yazdır / PDF</button><button id="saveBtn" class="reportbtn">Sonucu Kaydet (JSON)</button></section></aside></div><script>
const $=id=>document.getElementById(id);let files=[],last=null,expanded=false;const fieldIds=['research_title','application_type','is_student','research_nature','country','title','profession','institution','parent_institution','address','phone','email','participant_group','cities','unit','declared_tools','foreign_docs','av_record','minors','tool_origin','duplicate'];const esc=s=>String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));const meta=()=>Object.fromEntries(fieldIds.map(id=>[id,$(id).value]));const size=n=>n<1024?n+' B':n<1048576?(n/1024).toFixed(1)+' KB':(n/1048576).toFixed(1)+' MB';function renderFiles(){let w=$('fileCards');w.innerHTML='';files.forEach((f,i)=>{let d=document.createElement('div');d.className='filecard';d.innerHTML=`<div class="fileicon">${esc((f.name.split('.').pop()||'DOC').toUpperCase())}</div><div class="filemeta"><b title="${esc(f.name)}">${esc(f.name)}</b><span>${size(f.size)}</span></div><button class="remove">×</button>`;d.querySelector('button').onclick=()=>{files.splice(i,1);renderFiles()};w.appendChild(d)});$('analyzeBtn').disabled=!files.length}function add(fs){for(const f of fs)if(!files.some(x=>x.name===f.name&&x.size===f.size))files.push(f);renderFiles()}$('pickBtn').onclick=()=>$('fileInput').click();$('fileInput').onchange=e=>add(e.target.files);['dragenter','dragover'].forEach(x=>$('drop').addEventListener(x,e=>{e.preventDefault();$('drop').style.background='#eef8ff'}));['dragleave','drop'].forEach(x=>$('drop').addEventListener(x,e=>{e.preventDefault();$('drop').style.background=''}));$('drop').addEventListener('drop',e=>add(e.dataTransfer.files));$('clearBtn').onclick=()=>{files=[];last=null;renderFiles();$('criteriaBody').innerHTML='';$('riskGrid').innerHTML='';$('issues').innerHTML='Henüz sonuç yok.';$('strengths').innerHTML='Henüz sonuç yok.';$('counters').innerHTML='';$('note').textContent='Belgeler incelendikten sonra otomatik ön inceleme notu burada oluşacaktır.';setOverall(null)};const sclass=s=>'s-'+s.replaceAll(' ','');const lclass=s=>'l-'+s.replaceAll(' ','');function renderCriteria(items){let b=$('criteriaBody');b.innerHTML='';for(const r of items){let tr=document.createElement('tr');tr.innerHTML=`<td>${r.no}</td><td>${esc(r.criterion.length>170?r.criterion.slice(0,167)+'…':r.criterion)}</td><td><span class="status ${sclass(r.status)}">${esc(r.status)}</span></td><td>${esc(r.reason)} ▾</td>`;let dr=document.createElement('tr');dr.className='detailrow';dr.style.display=expanded?'table-row':'none';dr.innerHTML=`<td></td><td colspan="3"><div class="detail"><div><b>Tam Kriter</b>${esc(r.criterion)}</div><div><b>Gerekçe</b>${esc(r.reason)}</div><div><b>Kaynak Belge</b>${esc((r.source_docs||[]).join(', ')||'—')}</div><div><b>Kanıt / Dayanak</b>${esc(r.evidence||'—')}</div><div><b>Eksik Alt Koşullar</b>${esc((r.missing||[]).join(', ')||'—')}</div></div></td>`;tr.onclick=()=>dr.style.display=dr.style.display==='none'?'table-row':'none';b.append(tr,dr)}}function renderRisks(items){let g=$('riskGrid');g.innerHTML='';for(const r of items){let d=document.createElement('div');d.className='risk';d.innerHTML=`<div class="risktop"><span>${r.no}. ${esc(r.name)}</span><span class="level ${lclass(r.level)}">${esc(r.level)}</span></div><p>${esc(r.reason)}</p>${r.evidence?`<small><b>Kanıt:</b> ${esc(r.evidence)}</small>`:''}`;g.appendChild(d)}}function setOverall(r){let o=$('overall');if(!r){o.className='overall';o.innerHTML='<div class="big">…</div><div><h3>İNCELEME BEKLİYOR</h3><p>Belgeleri yükleyip İNCELE düğmesine basın.</p></div>';return}let cls='expert',icon='!';if(r==='Kabul Adayı'){cls='good';icon='✓'}else if(r==='Ret Adayı'){cls='bad';icon='×'}else if(r==='Eksik Başvuru'){cls='warn';icon='!'}o.className='overall '+cls;o.innerHTML=`<div class="big">${icon}</div><div><h3>${esc(r).toUpperCase()}</h3><p>Otomatik ön inceleme sonucu</p></div>`}function renderSide(j){let issues=j.criteria.filter(x=>!['Uygun','Uygulanmaz'].includes(x.status));$('issues').innerHTML=issues.length?issues.slice(0,10).map(x=>`<div class="sideitem"><b>${x.no}. kriter — ${esc(x.status)}</b><br>${esc(x.reason)}</div>`).join(''):'<div class="sideitem good">İncelenecek kriter bulunmadı.</div>';let goods=j.criteria.filter(x=>x.status==='Uygun');$('strengths').innerHTML=goods.length?goods.slice(0,7).map(x=>`<div class="sideitem good"><b>✓ ${x.no}. kriter</b><br>${esc(x.reason)}</div>`).join(''):'<div class="muted">Doğrulanmış güçlü uygunluk henüz yok.</div>';$('counters').innerHTML=Object.entries(j.counts).map(([k,v])=>`<div class="counter"><span>${esc(k)}</span><b>${v}</b></div>`).join('')}$('expandAll').onclick=()=>{expanded=!expanded;document.querySelectorAll('.detailrow').forEach(x=>x.style.display=expanded?'table-row':'none');$('expandAll').textContent=expanded?'Tümünü Daralt':'Tümünü Genişlet'};$('analyzeBtn').onclick=async()=>{if(!files.length)return;let btn=$('analyzeBtn');btn.disabled=true;$('progress').textContent='Belgeler okunuyor ve 30 kriter taranıyor…';try{let fd=new FormData();fd.append('metadata',JSON.stringify(meta()));files.forEach(f=>fd.append('files',f,f.name));let r=await fetch('/analyze',{method:'POST',body:fd});let j=await r.json();if(!r.ok)throw new Error(j.error||'İnceleme başarısız');last=j;renderCriteria(j.criteria);renderRisks(j.risks);$('note').textContent=j.note;setOverall(j.overall);renderSide(j);$('progress').textContent=j.warnings?.length?'İnceleme tamamlandı. Uyarı: '+j.warnings.join(' | '):'İnceleme tamamlandı.'}catch(e){$('progress').textContent='Hata: '+e.message;alert('İnceleme yapılamadı: '+e.message)}finally{btn.disabled=false}};$('printBtn').onclick=()=>{if(!last)return alert('Önce inceleme yapın.');window.print()};$('saveBtn').onclick=()=>{if(!last)return alert('Önce inceleme yapın.');let b=new Blob([JSON.stringify(last,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='arastirma_on_inceleme_sonucu.json';a.click();URL.revokeObjectURL(a.href)};renderFiles();setOverall(null);
</script></body></html>'''
